{
  "findings": [
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that even with chat set to \"no one\" Roblox can still allow in‑game chat if the game itself includes chat.",
      "stance": "risk",
      "quote": "even when chat is set to \"no one,\" if a mini-game has chat built into the game itself, it can't be disabled."
    },
    {
      "ref": "[D520]",
      "area": "contact",
      "claim": "A parent reports that kids can bypass disabled chats by writing text on \"signs\" that other players can see.",
      "stance": "risk",
      "quote": "Chatting on \"signs\" is another way that kids can get around parental controls that disable chats."
    },
    {
      "ref": "[D520]",
      "area": "money",
      "claim": "A parent reports that Roblox encourages spending on Robux and offers spending limits but does not prevent purchases.",
      "stance": "risk",
      "quote": "You can set a monthly spending limit on how much money your child can spend on Roblox."
    },
    {
      "ref": "[D520]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data and may share it, but parents can turn off ad personalization and data sharing.",
      "stance": "mitigation",
      "quote": "You can turn off ad personalization and data selling. You can also turn off data sharing."
    },
    {
      "ref": "[D520]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox requires an age check to chat and limits who can be contacted based on age.",
      "stance": "mitigation",
      "quote": "In order to chat, kids need to complete an age check. When they do, they can only talk to people of similar ages or people they know."
    },
    {
      "ref": "[D520]",
      "area": "content",
      "claim": "A parent reports that some experiences labeled 5+ contain intense violence or sensitive issues that may be inappropriate.",
      "stance": "risk",
      "quote": "Within seconds, this \"Street Code\" game showed an intense, fiery car accident and prompted the player to decide whether to shoot or save an officer."
    },
    {
      "ref": "[D520]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced fines or regulatory actions for data or privacy issues.",
      "stance": "risk",
      "quote": "Roblox uses automated moderation systems to limit the sharing of personal information and inappropriate content."
    }
  ]
}
